def _lower_first(s):
    return s[0].lower() + s[1:]


_ENG_BASE = {
    "approves": "approve",
    "checks": "check",
    "endorses": "endorse",
    "records": "record",
    "reviews": "review",
    "updates": "update",
    "provides": "provide",
    "prepares": "prepare",
    "publishes": "publish",
    "retains": "retain",
    "monitors": "monitor",
    "initiates": "initiate",
    "aligns": "align",
    "signs": "sign",
}


def _eng_base(v):
    return _ENG_BASE.get(v, v)


def _eng_past(v):
    b = _eng_base(v)
    return b + "d" if b.endswith("e") else b + "ed"


def make_sentence(rng, lex):
    t = rng.choice(lex["templates"])
    S = rng.choice(lex["S"])
    S2 = rng.choice([x for x in lex["S"] if x != S])
    V = rng.choice(lex["V"])
    V2 = rng.choice([x for x in lex["V"] if x != V])
    O = rng.choice(lex["O"])
    O2 = rng.choice([x for x in lex["O"] if x != O])
    fields = dict(
        S=S,
        s=_lower_first(S),
        s2=_lower_first(S2),
        V=V,
        V2=V2,
        O=O,
        O2=O2,
        T=rng.choice(lex["T"]),
        C=rng.choice(lex["C"]),
        I=rng.choice(lex["I"]),
        P=rng.choice(lex["P"]),
        D=rng.choice(lex["D"]),
        Vb=_eng_base(V),
        Vp=_eng_past(V),
    )
    return t.format(**fields)
